starter:
def digit_sum(n):
    # base case first, then call digit_sum on a smaller number
    pass

solution:
def digit_sum(n):
    if n < 10:
        return n
    return n % 10 + digit_sum(n // 10)

starter:
def doubles(start, count):
    # yield start, then keep doubling, count values in all
    pass

solution:
def doubles(start, count):
    value = start
    for _ in range(count):
        yield value
        value = value * 2
